package jbase.testlanguage.validation;

import org.eclipse.xtext.common.types.JvmField;
import org.eclipse.xtext.validation.Check;
import org.eclipse.xtext.xbase.XBlockExpression;
import org.eclipse.xtext.xbase.jvmmodel.IJvmModelAssociations;
import org.eclipse.xtext.xbase.validation.IssueCodes;

import com.google.inject.Inject;
import com.google.inject.Singleton;

import jbase.testlanguage.jbaseTestlanguage.AbstractOperation;
import jbase.testlanguage.jbaseTestlanguage.JbaseTestLanguageModel;
import jbase.testlanguage.jbaseTestlanguage.JbaseTestlanguagePackage;
import jbase.testlanguage.jbaseTestlanguage.Property;

/**
 * This class contains custom validation rules for our test language.
 *
 * This class is a singleton because we want to set specific fields in our tests,
 * so we want to make sure there's only a single instance that will be used
 * during our tests.
 */
@Singleton
public class JbaseTestlanguageValidator extends AbstractJbaseTestlanguageValidator {

	/**
	 * For testing purposes
	 */
	private boolean skipVariableInitializationCheck;

	@Inject
	private IJvmModelAssociations jvmModelAssociations;

	public void setSkipVariableInitializationCheck(final boolean skip) {
		skipVariableInitializationCheck = skip;
	}

	@Check
	public void checkReturnInOperation(final AbstractOperation op) {
		checkMissingReturn((XBlockExpression) op.getBody());
	}

	@Check
	public void checkVariableInitializationInMainBlock(final JbaseTestLanguageModel m) {
		if (!skipVariableInitializationCheck) {
			checkVariableInitialization(m.getBlock());
		}
	}

	@Check
	public void checkVariableInitializationInOperation(final AbstractOperation op) {
		if (!skipVariableInitializationCheck) {
			checkVariableInitialization((XBlockExpression) op.getBody());
		}
	}

	/**
	 * For testing purposes
	 */
	@Check
	public void checkLocalUsageOfDeclaredFields(final Property p) {
		var jvmField = jvmModelAssociations.getJvmElements(p).stream()
			.filter(JvmField.class::isInstance).map(JvmField.class::cast)
			.findFirst().orElse(null);
		if (jvmField != null && !isLocallyUsed(jvmField, p.eContainer())) {
			var message = "The value of the property " + p.getName() + " is not used";
			addIssueToState(IssueCodes.UNUSED_LOCAL_VARIABLE, message,
				JbaseTestlanguagePackage.Literals.PROPERTY__NAME);
		}
	}
}
